/**
 * Array of tuples mapping file extensions to language names:
 *
 * @example
 *     [
 *       [ "cpp", "C++" ],
 *       [ "ts", "TypeScript" ],
 *       // …
 *     ]
 */
export declare const extensionToLang: ReadonlyArray<[extension: string, langName: string]>;

/**
 * Alphabetically ordered array of language names.
 *
 * @example
 *     [
 *       "Elm",
 *       "Erlang",
 *       // …
 *     ]
 */
export declare const langNames: ReadonlyArray<string>;
